pub fn prime_num(n: u64) -> bool {
    // Assumption: n >= 2
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }

    // Check odd divisors up to sqrt(n) (inclusive).
    // If n has any divisor k in [2, n), it has one <= sqrt(n).
    let mut d: u64 = 3;
    while d <= n / d {
        if n % d == 0 {
            return false;
        }
        d += 2;
    }

    true
}